-- Read-only; exact known client releases, no actor inference, no mutation.
with target as (select * from public.product_events where environment='production' and is_test=false and onboarding_version='legacy' and client_release in ('proplet-v4.02.2-firststeps5','proplet-v4.02.2-metaacquisition2')) select client_release,event_type,count(*) as rows,count(distinct coalesce(player_id::text,anonymous_id)) as actors,min(created_at) as first_at,max(created_at) as last_at from target group by grouping sets ((),(client_release),(client_release,event_type)) order by client_release nulls first,event_type nulls first;
